// ============================================================
// CONFIG
// ============================================================
// O painel é quem reconhece as colunas e calcula, pelas regras da tela Configurações da página.
// Este node só coleta as linhas do Data Lab e as divide em lotes.
const CONFIG = {
  TAMANHO_LOTE: 500,               // linhas por envio ao painel (cada lote é um POST)
  PREFIXO_IGNORADO: "_",           // colunas técnicas do Data Lab (_cnpjOrigem, _razaoOrigem) não são enviadas
  DICIONARIO_ATE: 0.3,             // coluna de texto com poucos valores diferentes vai como índice
  NODE_GATILHO: "Todo dia 07:00",// de onde vem o carga_id quando o painel pede a atualização
  ORIGEM: "agendada",// agendada | botao
};

// ============================================================
// 1) Coletar as linhas (a saída do Data Lab vem aninhada em dados[].dados[])
// ============================================================
function ehLinha(o) {
  const ks = Object.keys(o);
  return ks.length >= 2 && ks.every((k) => o[k] === null || typeof o[k] !== "object");
}
function coletar(v, acc) {
  if (Array.isArray(v)) v.forEach((x) => coletar(x, acc));
  else if (v && typeof v === "object") {
    if (ehLinha(v)) acc.push(v);
    else Object.keys(v).forEach((k) => coletar(v[k], acc));
  }
  return acc;
}
const linhas = items.reduce((acc, it) => coletar(it.json, acc), []);
if (linhas.length === 0) throw new Error("O relatório do Data Lab não retornou linhas. Confira o ID do relatório no node Waipe Data.");

const colunas = [];
for (const l of linhas) for (const k of Object.keys(l)) {
  if (k.indexOf(CONFIG.PREFIXO_IGNORADO) !== 0 && colunas.indexOf(k) < 0) colunas.push(k);
}

// Colunas de texto repetitivo viram índice num dicionário (para a saída caber no limite de 1 MiB do node).
const dicionarios = {};
const indices = {};
for (const c of colunas) {
  const valores = {};
  let n = 0, texto = true;
  for (const l of linhas) {
    const v = l[c];
    if (v !== null && v !== undefined && typeof v !== "string") { texto = false; break; }
    const k = v === null || v === undefined ? "" : v;
    if (valores[k] === undefined) { valores[k] = n++; if (n > linhas.length * CONFIG.DICIONARIO_ATE) break; }
  }
  if (texto && n <= linhas.length * CONFIG.DICIONARIO_ATE) { indices[c] = valores; dicionarios[c] = Object.keys(valores); }
}
const compactas = linhas.map((l) => colunas.map((c) => {
  const v = l[c] === undefined ? null : l[c];
  return indices[c] ? indices[c][v === null ? "" : v] : v;
}));

// ============================================================
// 2) Identificar a carga e dividir em lotes
// ============================================================
let cargaId = "";
try { cargaId = String($node[CONFIG.NODE_GATILHO].json.carga_id || ""); } catch (e) { cargaId = ""; }
if (!cargaId) {
  const d = new Date();
  const p2 = (n) => String(n).padStart(2, "0");
  cargaId = "agendada-" + d.getUTCFullYear() + p2(d.getUTCMonth() + 1) + p2(d.getUTCDate()) + p2(d.getUTCHours()) + p2(d.getUTCMinutes())
    + "-" + Math.random().toString(36).slice(2, 8);
}
const totalLotes = Math.ceil(compactas.length / CONFIG.TAMANHO_LOTE);
console.log("Carga " + cargaId + ": " + compactas.length + " linhas, " + totalLotes + " lotes | colunas: " + colunas.join(", ")
  + " | em dicionário: " + Object.keys(dicionarios).join(", "));

const saida = [];
for (let i = 0; i < totalLotes; i++) {
  saida.push({ json: {
    carga_id: cargaId,
    origem: CONFIG.ORIGEM,
    lote: i + 1,
    total_lotes: totalLotes,
    total_linhas: compactas.length,
    colunas: colunas,
    dicionarios: dicionarios,
    linhas: compactas.slice(i * CONFIG.TAMANHO_LOTE, (i + 1) * CONFIG.TAMANHO_LOTE),
  } });
}
return saida;

// ============================================================
// CONFIG
// ============================================================
const CONFIG = {
  NODE_LOTES: "Preparar Lotes",  // node que montou os lotes (de onde vêm carga_id e total_linhas)
};

// Cada item é a resposta de um POST de lote. Erro em lote vira aviso para o painel marcar a carga como erro
// (o painel só mexe na base quando chegam todas as linhas).
const primeiro = $node[CONFIG.NODE_LOTES].json;
const falhas = [];
let aceitas = 0;
items.forEach((it, i) => {
  const r = it.json || {};
  if (r.status >= 200 && r.status < 300 && r.parsedBody && r.parsedBody.ok) aceitas += Number(r.parsedBody.recebidos) || 0;
  else falhas.push("lote " + (i + 1) + ": " + (r.httpError || r.networkError || ("HTTP " + r.status + " " + String(r.body || "").slice(0, 200))));
});
console.log("Lotes: " + items.length + " | itens aceitos: " + aceitas + " de " + primeiro.total_linhas + " linhas | falhas: " + falhas.length);
return [{ json: {
  carga_id: primeiro.carga_id,
  total_linhas: primeiro.total_linhas,
  erro: falhas.length ? falhas.join(" | ").slice(0, 1000) : "",
} }];
